#include "ui/ClientChatWindow.h"
#include "ui_ClientChatWindow.h"   // generated by AUTOUIC from ClientChatWindow.ui

#include <QStatusBar>
#include <QTime>

#include "ui/UiTexts.h"

namespace ui {

ClientChatWindow::ClientChatWindow(QWidget* parent)
    : QMainWindow(parent)
    , m_ui(std::make_unique<Ui::ClientChatWindow>())
{
    m_ui->setupUi(this);

    // Left panel keeps its width when the window is resized; the conversation takes the rest.
    m_ui->mainSplitter->setChildrenCollapsible(false);
    m_ui->mainSplitter->setStretchFactor(0, 0);
    m_ui->mainSplitter->setStretchFactor(1, 1);
    m_ui->mainSplitter->setSizes({300, 660});

    // Signal-to-signal connection: the window does not decide what sign-out means.
    connect(m_ui->signOutButton, &QPushButton::clicked, this, &ClientChatWindow::signOutRequested);

    applyMessagingPlaceholder();
}

ClientChatWindow::~ClientChatWindow() = default;

void ClientChatWindow::openSession(const QString& login, domain::UserRole role)
{
    const QString roleName = roleDisplayName(role);

    m_ui->userNameLabel->setText(login);
    m_ui->roleBadgeLabel->setText(roleName.toUpper());
    statusBar()->showMessage(tr("Signed in as %1").arg(login));

    m_ui->activityLogView->clear();
    logInfo(tr("Signed in as %1 (%2).").arg(login, roleName));
}

void ClientChatWindow::logInfo(const QString& message)
{
    // QTextBrowser::append() interprets its argument as HTML when it looks like HTML.
    // Escaping first guarantees that a message (e.g. containing a server error) can never inject markup.
    const QString line = QStringLiteral("[%1] %2")
                             .arg(QTime::currentTime().toString(QStringLiteral("HH:mm:ss")),
                                  message.toHtmlEscaped());
    m_ui->activityLogView->append(line);
}

void ClientChatWindow::logInfo(const std::string& message)
{
    logInfo(QString::fromStdString(message));
}

void ClientChatWindow::applyMessagingPlaceholder()
{
    m_ui->conversationTitleLabel->setText(tr("No conversation selected"));
    m_ui->conversationView->setHtml(
        QStringLiteral("<div style=\"text-align:center; margin-top:70px; color:#6B7488;\">"
                       "<p style=\"font-size:15pt; font-weight:600; color:#1B2333;\">%1</p>"
                       "<p>%2</p></div>")
            .arg(tr("You are signed in"),
                 tr("Messaging is coming in the next iteration.")));

    // Present but inactive until the messaging use cases exist.
    m_ui->contactSearchEdit->setEnabled(false);
    m_ui->findContactButton->setEnabled(false);
    m_ui->contactList->setEnabled(false);
    m_ui->messageEdit->setEnabled(false);
    m_ui->sendButton->setEnabled(false);
}

} // namespace ui
